import heapq

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)

    # Priority queue: (path_values, row, col)
    heap = []

    # Initialize the heap with all starting positions
    for i in range(n):
        for j in range(n):
            heapq.heappush(heap, ([grid[i][j]], i, j))

    while heap:
        path, row, col = heapq.heappop(heap)
        if len(path) == k:
            return path

        # Try all four directions
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = row + dr, col + dc
            if 0 <= r < n and 0 <= c < n:
                # Avoid revisiting the same cell in the same path
                new_path = path + [grid[r][c]]
                heapq.heappush(heap, (new_path, r, c))

    return []

