    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = ""
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 0:
                if space_count <= 2:
                    result += '_' * space_count
                else:
                    result += '-'
                space_count = 0
